const upsertWikiTypeConfig = `-- name: UpsertWikiTypeConfig :one
INSERT INTO wiki_type_configs (space_type_id, enabled, label, icon, seed_stubs, position)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (space_type_id) DO UPDATE
SET enabled = EXCLUDED.enabled,
    label = EXCLUDED.label,
    icon = EXCLUDED.icon,
    seed_stubs = EXCLUDED.seed_stubs,
    position = EXCLUDED.position
RETURNING space_type_id, enabled, label, icon, seed_stubs, position, created_at
`

type UpsertWikiTypeConfigParams struct {
	SpaceTypeID pgtype.UUID `json:"space_type_id"`
	Enabled     bool        `json:"enabled"`
	Label       *string     `json:"label"`
	Icon        *string     `json:"icon"`
	SeedStubs   bool        `json:"seed_stubs"`
	Position    int32       `json:"position"`
}

// Create or re-enable a wiki type for a space type (admin).
func (q *Queries) UpsertWikiTypeConfig(ctx context.Context, arg UpsertWikiTypeConfigParams) (WikiTypeConfig, error) {
	row := q.db.QueryRow(ctx, upsertWikiTypeConfig,
		arg.SpaceTypeID,
		arg.Enabled,
		arg.Label,
		arg.Icon,
		arg.SeedStubs,
		arg.Position,
	)
	var i WikiTypeConfig
	err := row.Scan(
		&i.SpaceTypeID,
		&i.Enabled,
		&i.Label,
		&i.Icon,
		&i.SeedStubs,
		&i.Position,
		&i.CreatedAt,
	)
	return i, err
}

const wikiTypeConfigExists = `-- name: WikiTypeConfigExists :one
SELECT EXISTS(SELECT 1 FROM wiki_type_configs WHERE space_type_id = $1) AS exists
`

func (q *Queries) WikiTypeConfigExists(ctx context.Context, spaceTypeID pgtype.UUID) (bool, error) {
	row := q.db.QueryRow(ctx, wikiTypeConfigExists, spaceTypeID)
	var exists bool
	err := row.Scan(&exists)
	return exists, err
}
